import java.nio.file.*;import java.util.*;import com.android.tools.smali.dexlib2.dexbacked.DexBackedDexFile;import com.android.tools.smali.dexlib2.iface.*;import app.hiro.swiftkey.patches.MethodContract;
public class NativeHash {public static void main(String[]a)throws Exception{for(Object co:new DexBackedDexFile(null,java.nio.ByteBuffer.wrap(Files.readAllBytes(Path.of(a[0])))).getClasses()){ClassDef c=(ClassDef)co;if(c.getType().equals("Lwb0/p1;"))for(Method m:c.getMethods())System.out.println(m.getName()+m.getParameterTypes()+m.getReturnType()+" "+MethodContract.sha256(m));}}}
